fn is_ascii_digit(c: char) -> bool {
    // Returns true iff c is between '0' and '9' inclusive.
    c >= '0' && c <= '9'
}

fn all_digits(s: String) -> bool {
    // Vacuously true for empty string.
    // Otherwise, check each character in turn.
    for ch in s.chars() {
        if !is_ascii_digit(ch) {
            return false;
        }
    }
    true
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_is_ascii_digit() {
        assert!(is_ascii_digit('0'));
        assert!(is_ascii_digit('5'));
        assert!(is_ascii_digit('9'));
        assert!(!is_ascii_digit('a'));
        assert!(!is_ascii_digit(' '));
        assert!(!is_ascii_digit('😊'));
    }

    #[test]
    fn test_all_digits() {
        assert!(all_digits("".to_string()));            // empty
        assert!(all_digits("0123456789".to_string()));  // all digits
        assert!(!all_digits("123x456".to_string()));    // contains non-digit
        assert!(!all_digits("１２３".to_string()));     // full‐width digits are not ASCII
        assert!(!all_digits("123😊456".to_string()));   // contains emoji
    }
}